// src/ChatUploader.jsx
import React, { useState } from 'react';
import axios from 'axios';
import './ChatUploader.css';

export default function ChatUploader() {
  const [file, setFile] = useState(null);
  const [question, setQuestion] = useState('');
  const [chatLog, setChatLog] = useState([]);
  const [loading, setLoading] = useState(false);
  const [uploadMsg, setUploadMsg] = useState('');

  const handleFileChange = (e) => {
    setFile(e.target.files[0]);
    setUploadMsg('');
  };

  const handleUpload = async (e) => {
    e.preventDefault();
    if (!file) return;

    const formData = new FormData();
    formData.append('file', file);

    try {
      setLoading(true);
      const res = await axios.post('http://localhost:8080/upload', formData);
      setUploadMsg(res.data.message || 'Upload successful.');
    } catch (err) {
      console.error(err);
      setUploadMsg('An error occurred.');
    } finally {
      setLoading(false);
    }
  };

  const askQuestion = async () => {
    if (!question.trim()) return;

    const currentQ = question.trim();
    setChatLog((prev) => [...prev, { type: 'user', text: currentQ }]);
    setQuestion('');
    try {
      setLoading(true);
      const res = await axios.post('http://localhost:8080/ask', { question: currentQ });
      setChatLog((prev) => [...prev, { type: 'assistant', text: res.data.answer }]);
    } catch (err) {
      console.error(err);
    } finally {
      setLoading(false);
    }
  };

  const handleKeyPress = (e) => {
    if (e.key === 'Enter') {
      e.preventDefault();
      askQuestion();
    }
  };

  return (
    <div className="container mt-4">
      <form onSubmit={handleUpload} encType="multipart/form-data">
        <div className="form-group">
          <label htmlFor="file">Choose file</label>
          <input type="file" className="form-control-file" onChange={handleFileChange} />
        </div>
        <button type="submit" className="btn btn-primary">Upload</button>
        <div className="mt-2 text-success">{uploadMsg}</div>
      </form>

      <div className="mt-4 row">
        <label className="col-md-2 col-form-label">Enter Text</label>
        <div className="col-md-7">
          <input
            type="text"
            className="form-control"
            value={question}
            onChange={(e) => setQuestion(e.target.value)}
            onKeyPress={handleKeyPress}
            disabled={loading}
          />
        </div>
        <div className="col-md-3">
          <button className="btn btn-primary w-100" onClick={askQuestion} disabled={loading}>
            Ask
          </button>
        </div>
      </div>

      <div className="mt-4" id="answer-box">
        {chatLog.map((item, i) => (
          <div key={i} className={`answer-maring-top d-block text-${item.type === 'user' ? 'right text-primary' : 'left text-dark'}`}>
            {item.text}
          </div>
        ))}
      </div>

      {loading && (
        <div id="spinner-div" className="d-flex justify-content-center align-items-center">
          <img src="/static/img/spiner_img.svg" alt="Loading..." />
        </div>
      )}
    </div>
  );
}
